'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { countWord, countLine } = require('../src/index.js');

test('countWord: known words', () => {
  const expected = {
    pond: 1, the: 1, frog: 1, jumps: 1,
    silent: 2, water: 2, hello: 2, table: 2, poem: 2,
    banana: 3, beautiful: 3, created: 3, computer: 3,
  };
  for (const [word, n] of Object.entries(expected)) {
    assert.equal(countWord(word), n, word);
  }
});

test('countWord: is case-insensitive', () => {
  assert.equal(countWord('BANANA'), 3);
  assert.equal(countWord('Hello'), 2);
  assert.equal(countWord('POND'), 1);
});

test('countWord: ignores punctuation and apostrophes', () => {
  assert.equal(countWord('Hello,'), 2);
  assert.equal(countWord("don't"), 1);
  assert.equal(countWord('"banana!"'), 3);
});

test('countWord: returns 0 when there are no letters', () => {
  assert.equal(countWord('---'), 0);
  assert.equal(countWord('42'), 0);
  assert.equal(countWord(''), 0);
});

test('countWord: letter-bearing words count at least 1', () => {
  for (const w of ['a', 'I', 'the', 'pond']) {
    assert.ok(countWord(w) >= 1, w);
  }
});

test('countLine: sums words split on whitespace', () => {
  assert.equal(countLine('banana hello table'), 7);
  assert.equal(countLine('silent water pond'), 5);
  assert.equal(countLine('beautiful pond'), 4);
  assert.equal(countLine('computer the table'), 6);
  assert.equal(countLine('  hello   the\tpond  '), 4);
});

test('countLine: splits on hyphens', () => {
  assert.equal(countLine('pond-frog'), 2);
  assert.equal(countLine('table-hello'), 4);
});

test('countLine: splits on em and en dashes', () => {
  assert.equal(countLine('pond\u2014frog'), 2);
  assert.equal(countLine('pond\u2013frog'), 2);
  assert.equal(countLine('banana\u2014hello'), 5);
});

test('countLine: empty or symbol-only lines are 0', () => {
  assert.equal(countLine(''), 0);
  assert.equal(countLine('   '), 0);
  assert.equal(countLine('--- 42'), 0);
});

test('countLine: is case-insensitive and ignores punctuation', () => {
  assert.equal(countLine('Hello, BANANA!'), 5);
});
EOF
