const { test } = require('node:test');
const assert = require('node:assert/strict');
const { analyze } = require('../src/index.js');

// 5 / 7 / 5
const L5a = 'silent water pond';   // 2+2+1
const L7 = 'banana hello table';   // 3+2+2
const L5b = 'beautiful hello';     // 3+2

test('analyze: a 5-7-5 poem is a haiku', () => {
  const r = analyze([L5a, L7, L5b].join('\n'));
  assert.deepEqual(r.counts, [5, 7, 5]);
  assert.equal(r.isHaiku, true);
  assert.deepEqual(r.lines, [
    { text: L5a, syllables: 5 },
    { text: L7, syllables: 7 },
    { text: L5b, syllables: 5 },
  ]);
});

test('analyze: handles CRLF line endings', () => {
  const r = analyze([L5a, L7, L5b].join('\r\n') + '\r\n');
  assert.deepEqual(r.counts, [5, 7, 5]);
  assert.equal(r.isHaiku, true);
  assert.equal(r.lines[0].text, L5a);
});

test('analyze: trims lines', () => {
  const r = analyze(`   ${L5a}  \n\t${L7}\t\n ${L5b} `);
  assert.deepEqual(r.lines.map((l) => l.text), [L5a, L7, L5b]);
  assert.equal(r.isHaiku, true);
});

